25	/**
26	 * Implementation for the {@linkComponentApi}
27	 *
28	 * @internal
29	 */
30	export class DefaultComponentsApi implements ComponentsApi {
31	  #components: Map<string, ComponentType<any>>;
32	
33	  static fromTree(tree: AppTree) {
34	    const componentEntries = tree.root.edges.attachments
35	      .get('components')
36	      ?.reduce((map, e) => {
37	        const data = e.instance?.getData(
38	          createComponentExtension.componentDataRef,
39	        );
40	        if (data) {
41	          map.set(data.ref.id, data.impl);
42	        }
43	        return map;
44	      }, new Map<string, ComponentType>());
45	    return new DefaultComponentsApi(componentEntries ?? new Map());
46	  }
47	
48	  constructor(components: Map<string, any>) {
49	    this.#components = components;
50	  }
51	
52	  getComponent<T extends {}>(ref: ComponentRef<T>): ComponentType<T> {
53	    const impl = this.#components.get(ref.id);
54	    if (!impl) {
55	      throw new Error(`No implementation found for component ref ${ref}`);
56	    }
57	    return impl;
58	  }
59	}
