27	
28	/** @public */
29	export function createComponentExtension<
30	  TProps extends {},
31	  TConfig extends {},
32	  TInputs extends AnyExtensionInputMap,
33	>(options: {
34	  ref: ComponentRef<TProps>;
35	  name?: string;
36	  disabled?: boolean;
37	  inputs?: TInputs;
38	  configSchema?: PortableSchema<TConfig>;
39	  loader:
40	    | {
41	        lazy: (values: {
42	          config: TConfig;
43	          inputs: Expand<ResolvedExtensionInputs<TInputs>>;
44	        }) => Promise<ComponentType<TProps>>;
45	      }
46	    | {
47	        sync: (values: {
48	          config: TConfig;
49	          inputs: Expand<ResolvedExtensionInputs<TInputs>>;
50	        }) => ComponentType<TProps>;
51	      };
52	}) {
53	  return createExtension({
54	    kind: 'component',
55	    namespace: options.ref.id,
56	    name: options.name,
57	    attachTo: { id: 'app', input: 'components' },
58	    inputs: options.inputs,
59	    disabled: options.disabled,
60	    configSchema: options.configSchema,
61	    output: {
62	      component: createComponentExtension.componentDataRef,
63	    },
64	    factory({ config, inputs, node }) {
65	      let ExtensionComponent: ComponentType<TProps>;
66	
67	      if ('sync' in options.loader) {
68	        ExtensionComponent = options.loader.sync({ config, inputs });
69	      } else {
70	        const lazyLoader = options.loader.lazy;
71	        ExtensionComponent = lazy(() =>
72	          lazyLoader({ config, inputs }).then(Component => ({
73	            default: Component,
74	          })),
75	        ) as unknown as ComponentType<TProps>;
76	      }
77	
78	      return {
79	        component: {
80	          ref: options.ref,
81	          impl: props => (
82	            <ExtensionBoundary node={node}>
83	              <ExtensionComponent {...(props as TProps)} />
84	            </ExtensionBoundary>
85	          ),
86	        },
87	      };
88	    },
89	  });
90	}
91	
